before.content:
    ToolDefinition tool = tools.stream().filter(value -> value.schema().name().equals(context.toolName()))
            .findFirst().orElseThrow();
    return switch (tool.permissionMode()) {
        case ALLOW -> ToolExecutionPolicy.Evaluation.allow(tool.sequential(), "tool-definition");
        case ASK -> ToolExecutionPolicy.Evaluation.ask(tool.sequential(), "tool-definition");
        case DENY -> ToolExecutionPolicy.Evaluation.deny("tool-definition");
    };
};
private final List<ToolInterceptor> toolInterceptors = new ArrayList<>();

after.content:
    ToolDefinition tool = tools.stream().filter(value -> value.schema().name().equals(context.toolName()))
            .findFirst().orElseThrow();
    return switch (tool.permissionMode()) {
        case ALLOW -> ToolExecutionPolicy.Evaluation.allow(
                tool.sequential(), PermissionDecider.RiskLevel.LOW, "tool-definition");
        case ASK -> ToolExecutionPolicy.Evaluation.ask(
                tool.sequential(), PermissionDecider.RiskLevel.MEDIUM, "tool-definition");
        case DENY -> ToolExecutionPolicy.Evaluation.deny(
                PermissionDecider.RiskLevel.HIGH, "tool-definition");
    };
};
private final List<ToolInterceptor> toolInterceptors = new ArrayList<>();
